mapper.select:
select fxrate0_.ID as fxid, fxrate0_.sourceID as sourceid, interfaces1_.sourceDesc as soucename, fxrate0_.CURR_ID as curID, fxcurrency2_.CURR_CODE as currency, fxrate0_.baseCurrID as baseCurID, fxcurrency3_.CURR_CODE as baseCurrency, fxrate0_.RATE_DATE as rateDate, fxrate0_.RATE as rate from FX_RATE fxrate0_, InterfaceSource interfaces1_, FX_CURRENCY fxcurrency2_, FX_CURRENCY fxcurrency3_ where fxrate0_.sourceID=interfaces1_.sourceID and fxrate0_.CURR_ID=fxcurrency2_.CURR_ID and fxrate0_.baseCurrID=fxcurrency3_.CURR_ID and fxrate0_.sourceID=#{sourceid}
and fxrate0_.CURR_ID=#{cur}
and fxrate0_.baseCurrID=#{baseCur}
and fxrate0_.RATE_DATE>=#{startDate}
and fxrate0_.RATE_DATE<=#{endDate}
order by fxrate0_.RATE_DATE desc, fxrate0_.ID desc
